'use client';

import { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';

const PROJECT_ID = 'd4ee97a93dc538bc7c23303cdd30814c';

// Provider compartilhado entre componentes (igual ao site)
let sharedProvider: any = null;

async function getProvider() {
  if (sharedProvider) return sharedProvider;
  const { EthereumProvider } = await import('@walletconnect/ethereum-provider');
  const p = await EthereumProvider.init({
    projectId: PROJECT_ID,
    chains: [137],
    showQrModal: true,
    qrModalOptions: { themeMode: 'dark' },
    metadata: {
      name: 'VETRA Dashboard',
      description: 'Transparency & Portfolio Management',
      url: typeof window !== 'undefined' ? window.location.origin : 'https://vetravtr.com',
      icons: [typeof window !== 'undefined' ? window.location.origin + '/favicon.svg' : 'https://vetravtr.com/favicon.svg'],
    },
  });
  p.on('disconnect', () => { sharedProvider = null; });
  p.on('accountsChanged', (a: string[]) => { });
  if (p.accounts?.length > 0) sharedProvider = p;
  return p;
}

interface WalletContextType {
  account: string | null;
  connecting: boolean;
  connect: () => Promise<void>;
  disconnect: () => Promise<void>;
  error: string | null;
}

const WalletContext = createContext<WalletContextType>({
  account: null, connecting: false,
  connect: async () => {}, disconnect: async () => {}, error: null,
});

export function WalletProvider({ children }: { children: React.ReactNode }) {
  const [account, setAccount] = useState<string | null>(null);
  const [connecting, setConnecting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const connect = useCallback(async () => {
    setConnecting(true);
    setError(null);
    try {
      if (account) return;
      const p = await getProvider();
      await p.connect();
      const addr = p.accounts?.[0];
      if (addr) {
        sharedProvider = p;
        setAccount(addr);
      }
    } catch (e: any) {
      if (e?.code !== 4001) {
        setError(e?.message || 'Connection failed');
      }
    } finally {
      setConnecting(false);
    }
  }, [account]);

  const disconnect = useCallback(async () => {
    if (sharedProvider) {
      try { await sharedProvider.disconnect(); } catch {}
    }
    sharedProvider = null;
    setAccount(null);
  }, []);

  return (
    <WalletContext.Provider value={{ account, connecting, connect, disconnect, error }}>
      {children}
    </WalletContext.Provider>
  );
}

export const useWallet = () => useContext(WalletContext);
